12	static void checkSingleInput(const IProcessor & transform)
13	{
14	    if (transform.getInputs().size() != 1)
15	        throw Exception(
16	            ErrorCodes::LOGICAL_ERROR,
17	            "Transform for chain should have single input, but {} has {} inputs",
18	            transform.getName(),
19	            transform.getInputs().size());
20	
21	    if (transform.getInputs().front().isConnected())
22	        throw Exception("Transform for chain has connected input", ErrorCodes::LOGICAL_ERROR);
23	}
24	
25	static void checkSingleOutput(const IProcessor & transform)
26	{
27	    if (transform.getOutputs().size() != 1)
28	        throw Exception(
29	            ErrorCodes::LOGICAL_ERROR,
30	            "Transform for chain should have single output, but {} has {} outputs",
31	            transform.getName(),
32	            transform.getOutputs().size());
33	
34	    if (transform.getOutputs().front().isConnected())
35	        throw Exception("Transform for chain has connected output", ErrorCodes::LOGICAL_ERROR);
36	}
37	
38	static void checkTransform(const IProcessor & transform)
39	{
40	    checkSingleInput(transform);
41	    checkSingleOutput(transform);
42	}
