44	static void checkInitialized(const std::list<ProcessorPtr> & processors)
45	{
46	    if (processors.empty())
47	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Chain is not initialized");
48	}
49	
50	Chain::Chain(ProcessorPtr processor)
51	{
52	    checkTransform(*processor);
53	    processors.emplace_back(std::move(processor));
54	}
55	
56	Chain::Chain(std::list<ProcessorPtr> processors_) : processors(std::move(processors_))
57	{
58	    if (processors.empty())
59	        return;
60	
61	    checkSingleInput(*processors.front());
62	    checkSingleOutput(*processors.back());
63	
64	    for (const auto & processor : processors)
65	    {
66	        for (const auto & input : processor->getInputs())
67	            if (&input != &getInputPort() && !input.isConnected())
68	                throw Exception(
69	                    ErrorCodes::LOGICAL_ERROR,
70	                    "Cannot initialize chain because there is a disconnected input for {}",
71	                    processor->getName());
72	
73	        for (const auto & output : processor->getOutputs())
74	            if (&output != &getOutputPort() && !output.isConnected())
75	                throw Exception(
76	                    ErrorCodes::LOGICAL_ERROR,
77	                    "Cannot initialize chain because there is a disconnected output for {}",
78	                    processor->getName());
79	    }
80	}
81	
82	void Chain::addSource(ProcessorPtr processor)
83	{
84	    checkTransform(*processor);
85	
86	    if (!processors.empty())
87	        connect(processor->getOutputs().front(), getInputPort());
88	
89	    processors.emplace_front(std::move(processor));
90	}
91	
92	void Chain::addSink(ProcessorPtr processor)
93	{
94	    checkTransform(*processor);
95	
96	    if (!processors.empty())
97	        connect(getOutputPort(), processor->getInputs().front());
98	
99	    processors.emplace_front(std::move(processor));
100	}
101	
102	IProcessor & Chain::getSource()
103	{
104	    checkInitialized(processors);
105	    return *processors.front();
106	}
107	
108	IProcessor & Chain::getSink()
109	{
110	    checkInitialized(processors);
111	    return *processors.back();
112	}
113	
114	InputPort & Chain::getInputPort() const
115	{
116	    checkInitialized(processors);
117	    return processors.front()->getInputs().front();
118	}
119	
120	OutputPort & Chain::getOutputPort() const
121	{
122	    checkInitialized(processors);
123	    return processors.back()->getOutputs().front();
124	}
